package com.clouddocs.document;
import com.clouddocs.auth.*;import com.clouddocs.audit.*;import com.clouddocs.permission.*;import com.clouddocs.storage.*;import com.clouddocs.work.*;import com.clouddocs.department.*;
import org.junit.jupiter.api.*;import org.springframework.mock.web.MockMultipartFile;import org.springframework.test.util.ReflectionTestUtils;import org.springframework.transaction.support.*;import org.springframework.security.access.AccessDeniedException;
import java.util.*;import java.time.Instant;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
class DocumentReplacementTest {
 final DocumentRepository documents=mock(DocumentRepository.class);final UserRepository users=mock(UserRepository.class);final S3StorageService s3=mock(S3StorageService.class);final LocalFileStorageService local=mock(LocalFileStorageService.class);final DocumentPermissionService permissions=mock(DocumentPermissionService.class);final AuditLogService audit=mock(AuditLogService.class);final WorkTaskRepository tasks=mock(WorkTaskRepository.class);final DepartmentService departments=mock(DepartmentService.class);
 final StorageQuotaService quotas=new StorageQuotaService(documents,users,100,1000,100);
 final DocumentService service=new DocumentService(documents,s3,local,users,permissions,audit,mock(AuditLogRepository.class),quotas,tasks,departments,"bucket");Document document;User editor,owner;
 final DocumentDtos.UpdateDocumentRequest request=new DocumentDtos.UpdateDocumentRequest("Edited title","Description","IT","ACTIVE");
 @BeforeEach void setup(){editor=new User();editor.setUsername("editor");editor.setFullName("Editor");ReflectionTestUtils.setField(editor,"id",4L);owner=new User();owner.setUsername("owner");owner.setFullName("Owner");ReflectionTestUtils.setField(owner,"id",3L);document=new Document();ReflectionTestUtils.setField(document,"id",9L);ReflectionTestUtils.setField(document,"updatedAt",Instant.now());document.setTitle("Old title");document.setFileName("old.txt");document.setFileType("TXT");document.setFileSize(50L);document.setDepartment("IT");document.setOwnerId(3L);document.setS3Key("documents/old");when(users.findByUsernameIgnoreCase("editor")).thenReturn(Optional.of(editor));when(users.findForStorageUpdate(3L)).thenReturn(Optional.of(owner));when(users.findAllById(any())).thenReturn(List.of(owner));when(documents.findById(9L)).thenReturn(Optional.of(document));when(documents.findForUpdate(9L)).thenReturn(Optional.of(document));when(documents.sumStorageExcludingDocument(3L,9L)).thenReturn(80L);when(documents.saveAndFlush(any())).thenAnswer(c->c.getArgument(0));when(documents.save(any())).thenAnswer(c->c.getArgument(0));when(permissions.canEdit(document,"editor",false)).thenReturn(true);when(permissions.effectiveAccess(document,editor)).thenReturn("EDIT");when(departments.documentName(any(),any())).thenReturn("IT");}
 @AfterEach void cleanup(){if(TransactionSynchronizationManager.isSynchronizationActive())TransactionSynchronizationManager.clearSynchronization();}
 MockMultipartFile file(int size){return new MockMultipartFile("file","new.pdf","application/pdf",new byte[size]);}
 @Test void metadataOnlyEditDoesNotTouchFileOrS3(){service.update(9L,request,"editor");assertEquals("old.txt",document.getFileName());assertEquals("documents/old",document.getS3Key());assertEquals("Edited title",document.getTitle());verifyNoInteractions(s3);}
 @Test void replacementPreservesDocumentIdOwnerAndOnlyDeletesOldObjectAfterCommit(){TransactionSynchronizationManager.initSynchronization();var result=service.replaceFile(9L,file(20),request,"editor");assertEquals(9L,result.id());assertEquals(3L,document.getOwnerId());assertEquals("new.pdf",result.fileName());assertEquals("PDF",result.fileType());assertEquals(20,result.fileSize());assertNotEquals("documents/old",document.getS3Key());verify(s3,never()).deleteIfExists(any(),any());TransactionSynchronizationManager.getSynchronizations().forEach(s->s.afterCompletion(TransactionSynchronization.STATUS_COMMITTED));verify(s3).deleteIfExists("bucket","documents/old");verify(local).deleteIfExists("documents/old");verify(audit).logInTransaction(eq("editor"),eq("REPLACE_FILE"),eq(9L),isNull(),contains("new.pdf"));verify(documents).sumStorageExcludingDocument(3L,9L);}
 @Test void uploadFailureKeepsOldObjectAndDoesNotSaveOrAudit(){doThrow(new IllegalStateException("S3 offline")).when(s3).uploadReplacement(any(),any(),any(),anyLong());assertThrows(IllegalStateException.class,()->service.replaceFile(9L,file(20),request,"editor"));assertEquals("documents/old",document.getS3Key());assertEquals("old.txt",document.getFileName());verify(s3,never()).deleteIfExists("bucket","documents/old");verify(documents,never()).saveAndFlush(any());verifyNoInteractions(audit);}
 @Test void rollbackRemovesOnlyNewCandidateAndKeepsOldFile(){TransactionSynchronizationManager.initSynchronization();doThrow(new IllegalStateException("DB failed")).when(documents).saveAndFlush(any());assertThrows(IllegalStateException.class,()->service.replaceFile(9L,file(20),request,"editor"));String candidate=document.getS3Key();TransactionSynchronizationManager.getSynchronizations().forEach(s->s.afterCompletion(TransactionSynchronization.STATUS_ROLLED_BACK));verify(s3).deleteIfExists("bucket",candidate);verify(s3,never()).deleteIfExists("bucket","documents/old");verifyNoInteractions(local,audit);}
 @Test void viewOnlyUserCannotReplace(){when(permissions.canEdit(document,"editor",false)).thenReturn(false);assertThrows(AccessDeniedException.class,()->service.replaceFile(9L,file(20),request,"editor"));verifyNoInteractions(s3);}
 @Test void pendingOrApprovedReportCannotBeOverwritten(){when(tasks.existsByReportDocumentIdAndStatusIn(eq(9L),anyCollection())).thenReturn(true);assertThrows(IllegalStateException.class,()->service.replaceFile(9L,file(20),request,"editor"));verifyNoInteractions(s3);}
 @Test void ownerQuotaCountsNewSizeInsteadOfOldSize(){assertThrows(IllegalStateException.class,()->service.replaceFile(9L,file(21),request,"editor"));verifyNoInteractions(s3);assertEquals("documents/old",document.getS3Key());}
 @Test void invalidFilenameRejectedBeforeUpload(){assertThrows(IllegalArgumentException.class,()->service.replaceFile(9L,new MockMultipartFile("file","../evil.pdf","application/pdf",new byte[1]),request,"editor"));verifyNoInteractions(s3);}
 @Test void emptyFileIsAValidReplacement(){assertEquals(0,service.replaceFile(9L,file(0),request,"editor").fileSize());}
}
